import sys
import os
import datetime
from typing import List, Tuple

def main():
    tasks: List[Tuple[str, bool]] = []
    log_file = "tasks.log"
    cache_file = "tasks.cache"

    # Load tasks from cache if it exists
    if os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            tasks = [tuple(line.strip().split(maxsplit=1)) for line in f if line.strip()]
        tasks = [(text, False) if text == '[x]' else (text, True) for text, completed in tasks]

    # Initialize log file if it doesn't exist
    if not os.path.exists(log_file):
        with open(log_file, 'a'):
            pass

    for line in sys.stdin:
        line = line.strip()
        command, *args = line.split(maxsplit=1) if line else ('-', '')
        command = command if command else '-'

        try:
            if command == 'add':
                if not args:
                    outcome = 'error'
                else:
                    text = args[0]
                    tasks.append((text, False))
                    outcome = 'ok'
            elif command == 'done':
                if not args:
                    outcome = 'error'
                else:
                    try:
                        n = int(args[0])
                        if 1 <= n <= len(tasks):
                            tasks[n-1] = (tasks[n-1][0], True)
                            outcome = 'ok'
                        else:
                            print(f"error: cannot complete task {n}", file=sys.stderr)
                            outcome = 'error'
                    except ValueError:
                        outcome = 'error'
            elif command == 'list':
                for i, (text, completed) in enumerate(tasks, 1):
                    status = '[x]' if completed else '[ ]'
                    print(f"{i} {status} {text}")
                outcome = 'ok'
            else:
                outcome = 'unknown'
        except Exception:
            outcome = 'error'

        # Log the command and outcome
        timestamp = datetime.datetime.utcnow().isoformat()
        with open(log_file, 'a') as f:
            f.write(f"{timestamp} {command} {outcome}\n")

    # Save tasks to cache
    with open(cache_file, 'w') as f:
        for text, completed in tasks:
            status = '[x]' if completed else '[ ]'
            f.write(f"{status} {text}\n")

if __name__ == "__main__":
    main()

