import sys
import os

class TaskCache:
    def __init__(self):
        self.tasks = []
        self.cache_file = "tasks.cache"
        self.log_file = "tasks.log"
        self.load_tasks()

    def load_tasks(self):
        if os.path.exists(self.cache_file):
            with open(self.cache_file, 'r') as f:
                self.tasks = [line.strip().split() for line in f.readlines()]
                self.tasks = [(text, completed) for text, completed in self.tasks]

    def save_tasks(self):
        with open(self.cache_file, 'w') as f:
            for text, completed in self.tasks:
                f.write(f"{text} {'done' if completed else 'pending'}\n")

    def log_entry(self, command, outcome):
        with open(self.log_file, 'a') as f:
            f.write(f"{command} {outcome}\n")

def main():
    cache = TaskCache()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            cache.log_entry("-", "unknown")
            continue
        parts = line.split(maxsplit=1)
        command = parts[0]
        if command == "add":
            if len(parts) < 2:
                cache.log_entry("add", "error")
                print("error: missing task text", file=sys.stderr)
                continue
            text = parts[1]
            cache.tasks.append((text, False))
            cache.log_entry("add", "ok")
        elif command == "done":
            try:
                n = int(parts[1])
            except ValueError:
                cache.log_entry("done", "error")
                print(f"error: cannot complete task {parts[1]}", file=sys.stderr)
                continue
            if 1 <= n <= len(cache.tasks):
                cache.tasks[n-1] = (cache.tasks[n-1][0], True)
                cache.log_entry("done", "ok")
            else:
                cache.log_entry("done", "error")
                print(f"error: cannot complete task {n}", file=sys.stderr)
        elif command == "list":
            for i, (text, completed) in enumerate(cache.tasks, 1):
                status = "[x]" if completed else "[ ]"
                print(f"{i} {status} {text}")
            cache.log_entry("list", "ok")
        else:
            cache.log_entry(command, "unknown")

    cache.save_tasks()

if __name__ == "__main__":
    main()
